  `nim` char(20) NOT NULL,
  `bayar` int(5) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM DEFAULT CHARSET=latin1;


DROP TABLE IF EXISTS `jabatan`;
CREATE TABLE `jabatan` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `nama` varchar(50) NOT NULL,
  `berlaku` int(1) NOT NULL,
  `ket` text NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=9 DEFAULT CHARSET=latin1;


DROP TABLE IF EXISTS `jadwal`;
CREATE TABLE `jadwal` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `tahun` char(10) NOT NULL,
  `kelas` int(1) NOT NULL,
  `urut` int(2) NOT NULL,
  `hari` int(1) NOT NULL,
  `jam` int(2) NOT NULL,
  `tm` int(1) NOT NULL,
  `mapel` char(20) NOT NULL,
  `guru` char(20) NOT NULL,
  `ket` text NOT NULL,
  `tingkat` int(2) NOT NULL,
  `masuk` text NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=1455 DEFAULT CHARSET=latin1;


DROP TABLE IF EXISTS `jadwal_guru`;
CREATE TABLE `jadwal_guru` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `hari` varchar(20) NOT NULL,
  `kelas` varchar(5) NOT NULL,
  `ket` varchar(20) NOT NULL,
  `jam` varchar(5) NOT NULL,
  `fan` varchar(100) NOT NULL,
  `nama` varchar(100) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=363 DEFAULT CHARSET=latin1;


DROP TABLE IF EXISTS `jam`;
CREATE TABLE `jam` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `nama` varchar(4) NOT NULL,
  `ket` varchar(50) NOT NULL,
  `mulai` time NOT NULL,
  `sampai` time NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=12 DEFAULT CHARSET=latin1;


DROP TABLE IF EXISTS `jenis`;
CREATE TABLE `jenis` (
  `id` int(1) NOT NULL AUTO_INCREMENT,
  `jenis` char(10) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=3 DEFAULT CHARSET=latin1;


DROP TABLE IF EXISTS `jurnal`;
CREATE TABLE `jurnal` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `tahun` date NOT NULL,
  `bulan` varchar(255) NOT NULL,
  `tanggal` varchar(255) NOT NULL,
  `tanggal_hijri` varchar(255) NOT NULL,
  `petugas` varchar(100) NOT NULL,
  `nokas` varchar(100) NOT NULL,
  `keterangan` varchar(255) DEFAULT NULL,
  `sumber` varchar(40) NOT NULL,
  `jam` time NOT NULL,
  `token` smallint(5) unsigned NOT NULL,
  `issync` tinyint(1) unsigned NOT NULL,
  PRIMARY KEY (`id`),
  KEY `IX_jurnal_tanggal` (`tahun`),
  KEY `IX_jurnal_ts` (`jam`,`issync`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;


DROP TABLE IF EXISTS `kabkot`;
CREATE TABLE `kabkot` (
  `id_prov` int(2) NOT NULL,
  `id_kabkot` int(4) NOT NULL,
  `nama_kabkot` char(40) NOT NULL
) ENGINE=MyISAM DEFAULT CHARSET=latin1;


DROP TABLE IF EXISTS `kas`;
CREATE TABLE `kas` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `tahun` char(10) NOT NULL,
  `tanggal` date NOT NULL,
  `tanggal_hijri` date NOT NULL,
  `akun` char(10) NOT NULL,
  `uraian` char(100) NOT NULL,
  `sumber` text NOT NULL,
  `debet` int(10) NOT NULL,
  `kredit` int(10) NOT NULL,
  `piutang` int(11) NOT NULL,
  `pendapatan` int(11) NOT NULL,
  `petugas` varchar(30) NOT NULL,
  `pemohon` varchar(50) NOT NULL,
  `penerima` varchar(50) NOT NULL,
  `waktu` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `akun` (`akun`),
  KEY `tanggal` (`tanggal`)
) ENGINE=MyISAM AUTO_INCREMENT=1358 DEFAULT CHARSET=latin1;


DROP TABLE IF EXISTS `kategori_akun`;
CREATE TABLE `kategori_akun` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `kategori` varchar(100) CHARACTER SET utf8 NOT NULL,
  `id_kategori` tinyint(1) unsigned NOT NULL DEFAULT '0',
  `info1` varchar(255) CHARACTER SET utf8 DEFAULT NULL,
  `info2` varchar(255) CHARACTER SET utf8 DEFAULT NULL,
  `info3` varchar(255) CHARACTER SET utf8 DEFAULT NULL,
  `ts` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `token` smallint(5) unsigned NOT NULL DEFAULT '0',
  `issync` tinyint(1) unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`kategori`),
  UNIQUE KEY `Index_1` (`id`),
  KEY `IX_katerekakun_ts` (`ts`,`issync`)
) ENGINE=MyISAM AUTO_INCREMENT=8 DEFAULT CHARSET=latin1;


DROP TABLE IF EXISTS `kec`;
CREATE TABLE `kec` (
  `id_prov` int(2) NOT NULL,
  `id_kabkot` int(4) NOT NULL,
  `id_kec` int(4) NOT NULL,
  `nama_kec` char(40) NOT NULL
) ENGINE=MyISAM DEFAULT CHARSET=latin1;


DROP TABLE IF EXISTS `kelas`;
CREATE TABLE `kelas` (
  `id` int(2) NOT NULL,
  `id_tingkat` int(3) NOT NULL,
  `tingkat` varchar(10) NOT NULL,
  `nama` varchar(6) NOT NULL,
  `nama_kelas` varchar(50) NOT NULL,
  `id_kelas` int(2) NOT NULL,
  `kelompok` int(2) NOT NULL,
  `tahun` varchar(20) NOT NULL,
  `ket` varchar(20) NOT NULL,
  `masuk` enum('SIANG','MALAM') NOT NULL,
  `status` enum('0','1') NOT NULL,
  `urut` int(2) NOT NULL
) ENGINE=MyISAM DEFAULT CHARSET=latin1;


DROP TABLE IF EXISTS `kkm`;
CREATE TABLE `kkm` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `tk_kesulitan` varchar(20) NOT NULL,
  `kelengkapan` varchar(20) NOT NULL,
  `kemampuan` varchar(20) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=4 DEFAULT CHARSET=utf8;


DROP TABLE IF EXISTS `koreksi`;
CREATE TABLE `koreksi` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `tahun` varchar(10) NOT NULL,
  `bulan` char(2) NOT NULL,
  `jenis` varchar(100) NOT NULL,
  `nig` int(10) NOT NULL,
  `biaya` int(10) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=241 DEFAULT CHARSET=latin1;


DROP TABLE IF EXISTS `level`;
CREATE TABLE `level` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `nama` varchar(100) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=5 DEFAULT CHARSET=latin1;


DROP TABLE IF EXISTS `libur`;
CREATE TABLE `libur` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `tahun` char(10) NOT NULL,
  `tanggal` date NOT NULL,
  `tanggal_hijri` date NOT NULL,
  `hari` char(20) NOT NULL,
  `tm` int(1) NOT NULL,
  `nig` char(20) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=94 DEFAULT CHARSET=latin1;


DROP TABLE IF EXISTS `mapel`;
CREATE TABLE `mapel` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
