  `avatar` text NOT NULL,
  `fan_pokok` int(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=1567 DEFAULT CHARSET=latin1;


DROP TABLE IF EXISTS `maulid`;
CREATE TABLE `maulid` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `tahun` varchar(10) NOT NULL,
  `bulan` char(2) NOT NULL,
  `tanggal` date NOT NULL,
  `tanggal_hijri` date NOT NULL,
  `kelas` int(11) NOT NULL,
  `nim` char(20) NOT NULL,
  `bayar` int(5) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=269 DEFAULT CHARSET=latin1;


DROP TABLE IF EXISTS `menu_kepala`;
CREATE TABLE `menu_kepala` (
  `id_kepala` int(11) NOT NULL,
  `nama_kepala` varchar(100) NOT NULL,
  `skrip_kepala` varchar(100) NOT NULL,
