  `icon` varchar(100) NOT NULL,
  `aktif` enum('Y','T') NOT NULL DEFAULT 'Y',
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `info` int(1) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=12 DEFAULT CHARSET=latin1;


DROP TABLE IF EXISTS `modul_sub`;
CREATE TABLE `modul_sub` (
  `id_sub` int(11) NOT NULL,
  `id_kepala` int(11) NOT NULL,
  `nama_sub` varchar(100) NOT NULL,
  `skrip_sub` varchar(100) NOT NULL,
  `level_sub` text NOT NULL,
  `aktif` enum('Y','T') NOT NULL DEFAULT 'Y',
  `icon` varchar(100) NOT NULL,
  `urut` int(11) NOT NULL,
  `id` int(11) NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=218 DEFAULT CHARSET=latin1;


DROP TABLE IF EXISTS `modul_sub_sub`;
CREATE TABLE `modul_sub_sub` (
  `id_sub_sub` int(11) NOT NULL,
  `id_sub` int(11) NOT NULL,
  `id_kepala` int(11) NOT NULL,
  `nama_sub_sub` varchar(100) NOT NULL,
  `skrip_sub_sub` varchar(100) NOT NULL,
  `level_sub_sub` text NOT NULL,
  `aktif` enum('Y','T') NOT NULL DEFAULT 'Y',
  `icon` varchar(100) NOT NULL,
  `urut` int(11) NOT NULL
) ENGINE=MyISAM DEFAULT CHARSET=latin1;


DROP TABLE IF EXISTS `murid`;
CREATE TABLE `murid` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `nim` int(11) NOT NULL,
  `nik` varchar(30) NOT NULL,
  `id_mmu` int(20) NOT NULL,
  `no_kk` varchar(30) NOT NULL,
  `nodaftar` int(11) NOT NULL,
  `angkatan` varchar(10) NOT NULL,
  `asal` varchar(50) NOT NULL,
  `tanggal_masuk` date NOT NULL,
  `tanggal_hijri` date NOT NULL,
  `masuk_kelas` int(1) NOT NULL,
  `nama` varchar(100) NOT NULL,
  `nama_akte` varchar(100) NOT NULL,
  `panggilan` varchar(100) NOT NULL,
  `jenis_kelamin` enum('LAKI-LAKI','PEREMPUAN') NOT NULL,
  `tempat_lahir` varchar(20) NOT NULL,
  `tanggal_lahir` date NOT NULL,
  `anakke` tinyint(2) NOT NULL,
  `jmlsaudara` tinyint(2) NOT NULL,
  `nama_ayah` varchar(200) NOT NULL,
  `tgllahirayah` int(10) NOT NULL,
  `nama_ibu` varchar(200) NOT NULL,
  `tgllahiribu` int(10) NOT NULL,
  `nama_wali` varchar(200) NOT NULL,
  `almayah` tinyint(1) unsigned NOT NULL,
  `almibu` tinyint(1) unsigned NOT NULL,
  `alamat` text NOT NULL,
  `desa` text NOT NULL,
  `kecamatan` varchar(200) NOT NULL,
  `wilayah` varchar(20) NOT NULL,
  `telepon` varchar(20) NOT NULL,
  `teleponibu` varchar(20) NOT NULL,
  `status` enum('AKTIF','LULUS','MUTASI','KELUAR') NOT NULL,
  `avatar` text NOT NULL,
  `valid` int(1) NOT NULL DEFAULT '0',
  `tingkat` int(1) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `nim` (`nim`),
  KEY `nodaftar` (`nodaftar`)
) ENGINE=MyISAM AUTO_INCREMENT=847 DEFAULT CHARSET=latin1;


DROP VIEW IF EXISTS `muridkelas`;
CREATE TABLE `muridkelas` (`tahun` varchar(10), `kelas` int(3), `nama_kelas` varchar(50), `nim` char(20), `jenis` enum('BARU','LAMA','TETAP'), `tingkat` int(1), `id_induk` int(20), `nama` varchar(100), `alamat` text, `kecamatan` varchar(200), `tanggal_lahir` date, `tempat_lahir` varchar(20), `nama_ayah` varchar(200), `nama_ibu` varchar(200));


